#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SessionInboxDelivery {
    /// "steer"
    Steer,
    /// "queue"
    Queue,
}

impl SessionInboxDelivery {
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Steer => "steer",
            Self::Queue => "queue",
        }
    }
}

impl Wire for SessionInboxDelivery {
    fn decode(v: &Json) -> Result<Self, Issue> {
        match v {
            Json::String(s) => match s.as_str() {
                "steer" => Ok(Self::Steer),
                "queue" => Ok(Self::Queue),
                _ => Err(rt::no_member(v, "SessionInboxDelivery")),
            },
            _ => Err(rt::no_member(v, "SessionInboxDelivery")),
        }
    }

    fn encode(&self, out: &mut Out) {
        match self {
            Self::Steer => out.string("steer"),
            Self::Queue => out.string("queue"),
        }
    }
}

