#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ShellInfoStatus {
    /// "running"
    Running,
    /// "exited"
    Exited,
    /// "timeout"
    Timeout,
    /// "killed"
    Killed,
}

impl ShellInfoStatus {
    pub const fn as_str(&self) -> &'static str {
        match self {
            Self::Running => "running",
            Self::Exited => "exited",
            Self::Timeout => "timeout",
            Self::Killed => "killed",
        }
    }
}

impl Wire for ShellInfoStatus {
    fn decode(v: &Json) -> Result<Self, Issue> {
        match v {
            Json::String(s) => match s.as_str() {
                "running" => Ok(Self::Running),
                "exited" => Ok(Self::Exited),
                "timeout" => Ok(Self::Timeout),
                "killed" => Ok(Self::Killed),
                _ => Err(rt::no_member(v, "ShellInfoStatus")),
            },
            _ => Err(rt::no_member(v, "ShellInfoStatus")),
        }
    }

    fn encode(&self, out: &mut Out) {
        match self {
            Self::Running => out.string("running"),
            Self::Exited => out.string("exited"),
            Self::Timeout => out.string("timeout"),
            Self::Killed => out.string("killed"),
        }
    }
}

