/// Marker emitted once when a log read reaches its captured watermark. The reader holds every event committed at or below seq.
#[derive(Debug, Clone, PartialEq)]
pub struct EventLogSynced {
    /// Wire key: `type`
    pub r#type: lit::LogSynced,
    /// Wire key: `aggregateID`
    pub aggregate_id: String,
    pub seq: Option<EventSeqPlain>,
}

impl Wire for EventLogSynced {
    fn decode(v: &Json) -> Result<Self, Issue> {
        let o = rt::object(v)?;
        Ok(Self {
            r#type: rt::required(o, "type", |v| <lit::LogSynced as Wire>::decode(v))?,
            aggregate_id: rt::required(o, "aggregateID", |v| <String as Wire>::decode(v))?,
            seq: rt::optional(o, "seq", |v| <EventSeqPlain as Wire>::decode(v))?,
        })
    }

    fn encode(&self, out: &mut Out) {
        let mut o = out.object();
        self.r#type.encode(o.key("type"));
        self.aggregate_id.encode(o.key("aggregateID"));
        if let Some(x) = &self.seq { x.encode(o.key("seq")); }
    }
}

