#[derive(Debug, Clone, PartialEq)]
pub enum FormField {
    FormStringField(FormStringField),
    FormNumberField(FormNumberField),
    FormIntegerField(FormIntegerField),
    FormBooleanField(FormBooleanField),
    FormMultiselectField(FormMultiselectField),
    FormExternalField(FormExternalField),
}

impl Wire for FormField {
    fn decode(v: &Json) -> Result<Self, Issue> {
        if rt::field_is(v, "type", rt::Lit::Str("string")) { if let Ok(x) = <FormStringField as Wire>::decode(v) { return Ok(Self::FormStringField(x)); } }
        if rt::field_is(v, "type", rt::Lit::Str("number")) { if let Ok(x) = <FormNumberField as Wire>::decode(v) { return Ok(Self::FormNumberField(x)); } }
        if rt::field_is(v, "type", rt::Lit::Str("integer")) { if let Ok(x) = <FormIntegerField as Wire>::decode(v) { return Ok(Self::FormIntegerField(x)); } }
        if rt::field_is(v, "type", rt::Lit::Str("boolean")) { if let Ok(x) = <FormBooleanField as Wire>::decode(v) { return Ok(Self::FormBooleanField(x)); } }
        if rt::field_is(v, "type", rt::Lit::Str("multiselect")) { if let Ok(x) = <FormMultiselectField as Wire>::decode(v) { return Ok(Self::FormMultiselectField(x)); } }
        if rt::field_is(v, "type", rt::Lit::Str("external")) { if let Ok(x) = <FormExternalField as Wire>::decode(v) { return Ok(Self::FormExternalField(x)); } }
        Err(rt::no_member(v, "FormField"))
    }

    fn encode(&self, out: &mut Out) {
        match self {
            Self::FormStringField(x) => x.encode(out),
            Self::FormNumberField(x) => x.encode(out),
            Self::FormIntegerField(x) => x.encode(out),
            Self::FormBooleanField(x) => x.encode(out),
            Self::FormMultiselectField(x) => x.encode(out),
            Self::FormExternalField(x) => x.encode(out),
        }
    }
}

